-- mod-city-bots — stage cast basic outfits (Recruit's Shirt 38 / Pants 39 / Boots 40).
--
-- Starter clothes so city bots do not load naked; duelers are geared up by the
-- module at runtime. Inn dancers (9000025, 9000026) intentionally stay
-- unclothed. Item GUID = 910100000 + (character guid - 9000001) * 10 + slot
-- offset (1 shirt, 2 legs, 3 feet); slots are equipment slots 3, 6, 7.
--
-- Self-contained: no reads from acore_playerbots / acore_world. Safe to
-- reapply: the shipped items are recreated, but a slot that already holds
-- another item (runtime gear) is left alone and the unused item is dropped.

DELETE FROM `character_inventory` WHERE `item` >= 910100000 AND `item` < 910110000;
DELETE FROM `item_instance`       WHERE `guid` >= 910100000 AND `guid` < 910110000;

















































-- Drop shipped items whose slot was already occupied (INSERT IGNORE above).
DELETE `ii` FROM `item_instance` `ii`
  LEFT JOIN `character_inventory` `ci` ON `ci`.`item` = `ii`.`guid`
 WHERE `ii`.`guid` >= 910100000 AND `ii`.`guid` < 910110000
   AND `ci`.`item` IS NULL;
